import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container
  const root = new Group();

  // Text handling (none for this node, but keep pattern)
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.role === 'headline' ? '#e8ecf2' : '#e8ecf2',
      align: 'left',
    });
    root.add(txt);
  }

  // Plane geometry based on atlas region (default 512x320)
  const atlas = config.atlasRegion ?? { srcX: 0, srcY: 0, srcW: 512, srcH: 320 };
  const aspect = atlas.srcW / atlas.srcH;
  const planeWidth = 7 * aspect; // arbitrary scaling within hub frame
  const planeHeight = 7;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);

  // Material – start without texture
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  material.depthWrite = false;

  const mesh = new Mesh(geometry, material);
  mesh.renderOrder = 1; // ensure it renders above backdrop if needed

  // Billboard to camera
  mesh.onBeforeRender = (_, __, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  root.add(mesh);

  // Load texture and apply UV transform for atlas region
  let texture = null;
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    texture = tex;
    material.map = tex;
    // After texture loads we can set offset/repeat based on atlas region
    const texW = tex.image?.width ?? 1;
    const texH = tex.image?.height ?? 1;
    tex.offset.set(atlas.srcX / texW, atlas.srcY / texH);
    tex.repeat.set(atlas.srcW / texW, atlas.srcH / texH);
    tex.needsUpdate = true;
  });

  // Store references for cleanup
  const cleanupRefs = [];

  // Apply cinematic primitives if any
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        const instance = fn(root, prim.params);
        cleanupRefs.push(instance);
      }
    }
  }

  // UserData handlers (none for this node)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();
    // Dispose texture if loaded
    if (texture) texture.dispose();
    // Kill any GSAP timelines (none created here)
    gsap.globalTimeline.clear();
    // Cleanup primitives
    for (const ref of cleanupRefs) {
      if (ref && typeof ref.cleanup === 'function') ref.cleanup();
    }
    // Remove onBeforeRender
    mesh.onBeforeRender = null;
  };

  // Ensure any async texture load does not break cleanup
  root.userData._texPromise = texPromise;

  return root;
}
